toolScript:
// --- State ---
        let port = null;
        let reader = null;
        let isSimulating = false;
        // --- DOM Elements ---
        const terminal = document.getElementById('terminal-log');
        const statusBadge = document.getElementById('status-badge');
        const valVolts = document.getElementById('val-volts');
        const valAmps = document.getElementById('val-amps');
        const valWatts = document.getElementById('val-watts');
        const valEmarker = document.getElementById('val-emarker');
        const serialIndicator = document.getElementById('serial-indicator');
        const serialText = document.getElementById('serial-text');
        const btnSerial = document.getElementById('btn-serial');
        const btnDemo = document.getElementById('btn-demo');
        // --- Terminal Logic ---
        function logTerm(msg, type = 'sys') {
            const line = document.createElement('div');
            // Generate pseudo-timestamp
            const d = new Date();
            const ts = `[${d.getSeconds().toString().padStart(2, '0')}.${d.getMilliseconds().toString().padStart(3, '0')}s]`;
            line.innerHTML = `<span class="term-ts">${ts}</span><span class="term-${type}">${msg}</span>`;
            terminal.appendChild(line);
            // Auto scroll
            terminal.scrollTop = terminal.scrollHeight;
        }
        function clearTerm() {
            terminal.innerHTML = '';
        }
        // --- Parsing Logic (Mock/Real) ---
        function setDashboardValues(v, a, emarkerStatus) {
            valVolts.innerText = v.toFixed(1);
            valAmps.innerText = a.toFixed(1);
            valWatts.innerText = Math.round(v * a);
            if (emarkerStatus) {
                valEmarker.innerText = emarkerStatus;
                if (emarkerStatus.includes("100W") || emarkerStatus.includes("240W")) {
                    valEmarker.className = "data-display text-sm text-emerald-400 font-bold";
                } else {
                    valEmarker.className = "data-display text-sm text-slate-300 font-bold";
                }
            }
        }
        // --- Demo Simulation Flow ---
        async function runSimulation() {
            if (isSimulating || port) return;
            isSimulating = true;
            // Update UI State
            btnDemo.classList.replace('bg-amber-500', 'bg-slate-700');
            btnDemo.classList.replace('hover:bg-amber-600', 'hover:bg-slate-800');
            btnDemo.classList.replace('border-amber-700', 'border-slate-900');
            btnDemo.innerHTML = `<svg class="w-5 h-5 animate-spin text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span>Simulating...</span>`;
            serialIndicator.classList.replace('bg-slate-300', 'bg-amber-400');
            serialIndicator.classList.add('animate-pulse');
            serialText.innerText = "Simulated Hardware";
            clearTerm();
            setDashboardValues(0, 0, "Scanning...");
            statusBadge.innerText = "Negotiating...";
            statusBadge.className = "status-pill status-negotiating";
            logTerm("Starting simulated PD Sniffer Hardware...", "sys");
            const wait = (ms) => new Promise(res => setTimeout(res, ms));
            await wait(800);
            logTerm("SINK ATTACHED. CC1 Pulled down.", "sys");
            await wait(400);
            logTerm(">> [SRC] Source_Capabilities (0x01)", "tx");
            logTerm("   - PDO 1: Fixed 5.0V / 3.0A (15.0W)", "tx");
            await wait(100);
            logTerm("   - PDO 2: Fixed 9.0V / 3.0A (27.0W)", "tx");
            await wait(100);
            logTerm("   - PDO 3: Fixed 15.0V / 3.0A (45.0W)", "tx");
            await wait(100);
            logTerm("   - PDO 4: Fixed 20.0V / 5.0A (100.0W)", "tx");
            await wait(600);
            logTerm("<< [SNK] Discover_Identity (VDM)", "rx");
            await wait(200);
            logTerm(">> [CBL] Discover_Identity_ACK", "tx");
            logTerm("   - E-Marker Found: 5A Capable, USB4 Gen3", "sys");
            setDashboardValues(5, 3, "Verified 5A Active Cable (100W+)");
            await wait(500);
            logTerm("<< [SNK] Request (0x02) - Object 4", "rx");
            logTerm("   - Req: 20.0V @ 5.0A", "rx");
            await wait(300);
            logTerm(">> [SRC] Accept (0x03)", "tx");
            await wait(400);
            logTerm(">> [SRC] PS_RDY (0x06)", "tx");
            logTerm("VBUS Ramp Complete. Contract Established.", "sys");
            setDashboardValues(20.0, 5.0, "Verified 5A Active Cable (100W+)");
            statusBadge.innerText = "Contract Locked";
            statusBadge.className = "status-pill status-stable";
            // Reset Button
            await wait(1000);
            isSimulating = false;
            btnDemo.classList.replace('bg-slate-700', 'bg-amber-500');
            btnDemo.classList.replace('hover:bg-slate-800', 'hover:bg-amber-600');
            btnDemo.classList.replace('border-slate-900', 'border-amber-700');
            btnDemo.innerHTML = `<svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z"></path></svg><span>Run Simulated Handshake</span>`;
            serialIndicator.classList.remove('animate-pulse');
        }
        // --- WebSerial Hardware API ---
        async function requestSerialPort() {
            if (!("serial" in navigator)) {
                logTerm("Error: WebSerial API not supported in this browser. Use Chrome/Edge or use the simulation.", "err");
                return;
            }
            if (port) {
                // Disconnect logic
                try {
                    await port.close();
                } catch (e) {
                    console.error(e);
                }
                port = null;
                btnSerial.innerHTML = `<svg class="w-5 h-5 text-cyan-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 9l3 3-3 3m5 0h3M5 20h14a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg><span>Connect Hardware Sniffer</span>`;
                btnSerial.classList.replace('bg-red-600', 'bg-slate-800');
                btnSerial.classList.replace('hover:bg-red-700', 'hover:bg-slate-900');
                btnSerial.classList.replace('border-red-800', 'border-slate-950');
                serialIndicator.classList.replace('bg-cyan-400', 'bg-slate-300');
                serialIndicator.classList.remove('animate-pulse');
                serialText.innerText = "Detached";
                logTerm("Disconnected from Hardware.", "sys");
                return;
            }
            try {
                port = await navigator.serial.requestPort();
                await port.open({ baudRate: 115200 }); // Standard baud for Arduino/ESP32 sniffers
                logTerm("Hardware Connected! Listening for CC events...", "sys");
                // UI updates
                btnSerial.innerHTML = `<svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg><span>Disconnect Hardware</span>`;
                btnSerial.classList.replace('bg-slate-800', 'bg-red-600');
                btnSerial.classList.replace('hover:bg-slate-900', 'hover:bg-red-700');
                btnSerial.classList.replace('border-slate-950', 'border-red-800');
                serialIndicator.classList.replace('bg-slate-300', 'bg-cyan-400');
                serialIndicator.classList.add('animate-pulse');
                serialText.innerText = "Live Capture";
                statusBadge.innerText = "Listening...";
                statusBadge.className = "status-pill status-negotiating";
                readLoop();
            } catch (err) {
                logTerm("Connection Failed: " + err.message, "err");
                port = null;
            }
        }
        async function readLoop() {
            while (port && port.readable) {
                reader = port.readable.getReader();
                try {
                    while (true) {
                        const { value, done } = await reader.read();
                        if (done) {
                            break;
                        }
                        // Decode Uint8Array to text
                        const text = new TextDecoder().decode(value);
                        // Basic Parsing logic assuming standard serial printout from a sniffer 
                        // e.g., "TX: SRC_CAP 20V 5A"
                        const lines = text.split('\n');
                        for (let line of lines) {
                            if (line.trim().length === 0) continue;
                            let type = 'sys';
                            if (line.includes("TX") || line.includes("SRC")) type = 'tx';
                            if (line.includes("RX") || line.includes("SNK")) type = 'rx';
                            logTerm(line.trim(), type);
                            // Try to extract power data dynamically if present
                            if (line.includes("Accept") || line.includes("PS_RDY")) {
                                statusBadge.innerText = "Contract Locked";
                                statusBadge.className = "status-pill status-stable";
                            }
                        }
                    }
                } catch (error) {
                    logTerm("Read error: " + error, "err");
                } finally {
                    reader.releaseLock();
                }
            }
        }
        // --- Scroll Logic ---
